j._source = 'RemoteOK';
return { json: j };

const j = $input.item.json;
j._source = 'Remotive';
return { json: j };

const j = $input.item.json;
j._source = 'WWR';
return { json: j };

const j = $input.item.json;
j._source = 'WWR';
return { json: j };

const j = $input.item.json;
j._source = 'Himalayas';
return { json: j };

const src = $json._source;
let job = {};

if (src === 'RemoteOK') {
  job = {
    job_title: $json.position || $json.title || '',
    company: $json.company || '',
    job_url: $json.url || $json.apply_url || ('https://remoteok.com/remote-jobs/' + ($json.id || $json.slug || '')),
    source: 'Remote OK',
    location_text: $json.location || 'Worldwide',
    salary: ($json.salary_min && $json.salary_max) ? ('$' + $json.salary_min + ' - $' + $json.salary_max) : ($json.salary || ''),
    description: ($json.description || '').toString(),
    posted_date: $json.date || '',
    tags: Array.isArray($json.tags) ? $json.tags.join(', ') : ($json.tags || '')
  };
} else if (src === 'Remotive') {
  job = {
    job_title: $json.title || '',
    company: $json.company_name || '',
    job_url: $json.url || '',
    source: 'Remotive',
    location_text: $json.candidate_required_location || 'Worldwide',
    salary: $json.salary || '',
    description: ($json.description || '').toString(),
    posted_date: $json.publication_date || '',
    tags: Array.isArray($json.tags) ? $json.tags.join(', ') : ($json.tags || '')
  };
} else if (src === 'WWR') {
  const rawTitle = $json.title || '';
  const parts = rawTitle.split(':');
  job = {
    job_title: parts.length > 1 ? parts.slice(1).join(':').trim() : rawTitle,
    company: parts.length > 1 ? parts[0].trim() : '',
    job_url: $json.link || $json.guid || '',
    source: 'We Work Remotely',
    location_text: 'See description',
    salary: '',
    description: $json.contentSnippet || $json.content || $json.summary || '',
    posted_date: $json.isoDate || $json.pubDate || '',
    tags: Array.isArray($json.categories) ? $json.categories.join(', ') : ''
  };
} else if (src === 'Himalayas') {
  job = {
    job_title: $json.title || '',
    company: $json.companyName || (($json.company || {}).name) || '',
    job_url: $json.applyUrl || $json.guid || $json.url || '',
    source: 'Himalayas',
    location_text: Array.isArray($json.locationRestrictions) && $json.locationRestrictions.length ? $json.locationRestrictions.join(', ') : 'Worldwide',
    salary: (($json.salaryRange || {}).min || ($json.salaryRange || {}).max) ? ('$' + (($json.salaryRange || {}).min || '?') + ' - $' + (($json.salaryRange || {}).max || '?')) : '',
    description: $json.excerpt || $json.description || '',
    posted_date: $json.pubDate || $json.publishedAt || '',
    tags: Array.isArray($json.categories) ? $json.categories.join(', ') : ''
  };
} else {
  job = {
    job_title: $json.title || $json.job_title || '',
    company: $json.company || '',
    job_url: $json.url || $json.link || '',
    source: src || 'Unknown',
    location_text: $json.location || '',
    salary: $json.salary || '',
    description: $json.description || '',
    posted_date: $json.date || '',
    tags: ''
  };
}

job.job_title = (job.job_title || '').toString().trim();
job.company = (job.company || '').toString().trim();
job.job_url = (job.job_url || '').toString().trim();
job.description = (job.description || '').toString();

return { json: job };

const SEARCH_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote', 'work from anywhere',
  'remote data analyst', 'remote data scientist', 'remote ai marketing', 'remote marketing analyst',
  'remote growth analyst', 'remote bi analyst', 'remote automation specialist', 'remote ai workflow consultant'
];

const items = $input.all();
const out = [];

for (const item of items) {
  const j = item.json;
  if (!j.job_title || !j.job_url) continue;
  const haystack = (j.job_title + ' ' + j.description + ' ' + j.tags).toLowerCase();
  const matched = SEARCH_KEYWORDS.some(function (k) { return haystack.includes(k); });
  if (matched) out.push(item);
}

return out;

const existing = $('Get Existing Raw Jobs').all().map(function (i) { return i.json; });
const existingUrls = new Set(existing.map(function (r) { return (r.job_url || '').trim(); }).filter(Boolean));
const existingKeys = new Set(existing.map(function (r) { return ((r.company || '') + '::' + (r.job_title || '')).toLowerCase().trim(); }));

function hashId(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) | 0; }
  return 'job_' + Math.abs(h).toString(36);
}

const seenInBatch = new Set();
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const key = ((j.company || '') + '::' + (j.job_title || '')).toLowerCase().trim();
  if (existingUrls.has(url) || existingKeys.has(key)) continue;
  if (seenInBatch.has(url) || seenInBatch.has(key)) continue;
  seenInBatch.add(url);
  seenInBatch.add(key);
  j.job_id = hashId(url || key);
  j.date_found = new Date().toISOString().slice(0, 10);
  out.push({ json: j });
}

return out;

const j = $input.item.json;

const REJECT_PATTERNS = [
  { phrase: 'us only', category: 'us_only' },
  { phrase: 'u.s. only', category: 'us_only' },
  { phrase: 'united states only', category: 'us_only' },
  { phrase: 'canada only', category: 'other_region_locked' },
  { phrase: 'uk only', category: 'other_region_locked' },
  { phrase: 'united kingdom only', category: 'other_region_locked' },
  { phrase: 'eu only', category: 'eu_only' },
  { phrase: 'europe only', category: 'eu_only' },
  { phrase: 'australia only', category: 'other_region_locked' },
  { phrase: 'must be based in', category: 'must_be_based_in' },
  { phrase: 'must live in', category: 'must_be_based_in' },
  { phrase: 'must be authorized to work in', category: 'work_permit' },
  { phrase: 'local work permit required', category: 'work_permit' },
  { phrase: 'hybrid', category: 'hybrid' },
  { phrase: 'onsite', category: 'hybrid' },
  { phrase: 'on-site', category: 'hybrid' },
  { phrase: 'office required', category: 'hybrid' },
  { phrase: 'remote within country only', category: 'other_region_locked' },
  { phrase: 'fixed us hours', category: 'timezone' },
  { phrase: 'fixed eu hours', category: 'timezone' }
];

const KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere',
  'apac remote', 'international contractors accepted', 'contractor role',
  'b2b contractor', 'hires via deel', 'hires via remote.com', 'hires via oyster',
  'eor supported', 'remote first', 'distributed team'
];

const text = ((j.job_title || '') + ' ' + (j.description || '') + ' ' + (j.location_text || '') + ' ' + (j.tags || '')).toLowerCase();

let rejectCategory = null;
for (const p of REJECT_PATTERNS) {
  if (text.includes(p.phrase)) { rejectCategory = p.category; break; }
}

const keepMatched = KEEP_PHRASES.some(function (p) { return text.includes(p); });

j.hardFilterReject = !!rejectCategory;
j.hardFilterRejectCategory = rejectCategory;
j.hardFilterKeepMatched = keepMatched;

return { json: j };

const j = $input.item.json;
j.decision = 'reject';
j.reject_category = j.hardFilterRejectCategory || 'other_hardfilter';
j.date_rejected = new Date().toISOString().slice(0, 10);
j.reason = 'Hard filter match: ' + j.reject_category;
j.taiwan_eligible = 'no';
j.location_risk = 'high';
j.timezone_risk = j.reject_category === 'timezone' ? 'high' : 'unknown';
j.score = 0;
return { json: j };

const original = $('Prepare AI Prompt Payload').item.json;
const response = $input.item.json;

let text = '';
if (Array.isArray(response.content) && response.content.length && response.content[0].text) {
  text = response.content[0].text;
} else if (typeof response.content === 'string') {
  text = response.content;
}

const startIdx = text.indexOf('{');
const endIdx = text.lastIndexOf('}');
let parsed = {};
if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
  try { parsed = JSON.parse(text.slice(startIdx, endIdx + 1)); } catch (e) { parsed = {}; }
}

const j = original;
j.taiwan_eligible = (parsed.taiwan_eligible || 'unclear').toLowerCase();
j.taiwan_reason = parsed.reason || 'AI response could not be parsed';
j.location_risk = (parsed.location_risk || 'medium').toLowerCase();
j.timezone_risk = (parsed.timezone_risk || 'medium').toLowerCase();
j.contractor_possible = (parsed.contractor_possible || 'unclear').toLowerCase();
j.ai_decision = (parsed.decision || 'manual_check').toLowerCase();

return { json: j };

const j = $input.item.json;

const ASYNC_HARD_REJECT_PHRASES = [
  'strict 9 to 5', 'strict 9-to-5', 'fixed us hours', 'fixed est hours',
  'fixed pst hours', 'fixed cet hours', 'daily live calls required',
  'must overlap full business day'
];

const ASYNC_KEEP_TIERS = [
  { phrase: 'async', level: 'high', points: 25 },
  { phrase: 'asynchronous', level: 'high', points: 25 },
  { phrase: 'flexible hours', level: 'medium', points: 20 },
  { phrase: 'flexible schedule', level: 'medium', points: 20 },
  { phrase: 'low meeting culture', level: 'medium', points: 20 },
  { phrase: 'work across time zones', level: 'medium', points: 20 },
  { phrase: 'distributed team', level: 'medium', points: 15 },
  { phrase: 'remote first', level: 'low', points: 10 }
];

const text = ((j.job_title || '') + ' ' + (j.description || '') + ' ' + (j.tags || '')).toLowerCase();

const hardReject = ASYNC_HARD_REJECT_PHRASES.some(function (p) { return text.includes(p); });

let bestPoints = 0;
let bestLevel = 'unclear';
for (const tier of ASYNC_KEEP_TIERS) {
  if (text.includes(tier.phrase) && tier.points > bestPoints) {
    bestPoints = tier.points;
    bestLevel = tier.level;
  }
}

j.asyncHardReject = hardReject;
j.async_level = bestLevel;
j.async_points = bestPoints;

return { json: j };

const j = $input.item.json;
j.decision = 'reject';
j.reject_category = 'timezone';
j.date_rejected = new Date().toISOString().slice(0, 10);
j.reason = 'Rejected for rigid or overnight working hours';
j.timezone_risk = 'high';
j.score = 0;
return { json: j };

const j = $input.item.json;

const ROLE_CORE = [
  'data analyst', 'data scientist', 'junior data scientist', 'business intelligence analyst',
  'bi analyst', 'marketing analyst', 'performance marketing analyst', 'growth analyst',
  'ai marketing specialist', 'ai automation specialist', 'ai workflow consultant',
  'creative strategist', 'martech analyst'
];

const ROLE_ADJACENT = [
  'marketing specialist', 'digital marketing', 'analytics', 'automation specialist',
  'growth marketing', 'seo', 'ppc', 'crm', 'reporting analyst'
];

const text = ((j.job_title || '') + ' ' + (j.description || '') + ' ' + (j.tags || '')).toLowerCase();

const coreMatch = ROLE_CORE.some(function (p) { return text.includes(p); });
const adjacentMatch = !coreMatch && ROLE_ADJACENT.some(function (p) { return text.includes(p); });

j.role_category = coreMatch ? 'core' : (adjacentMatch ? 'adjacent' : 'other');
j.role_points = coreMatch ? 25 : (adjacentMatch ? 15 : 0);

return { json: j };

const j = $input.item.json;

let taiwanPoints = 0;
if (j.taiwan_eligible === 'no' || j.hardFilterReject) {
  taiwanPoints = 0;
} else if (j.hardFilterKeepMatched) {
  const text = ((j.job_title || '') + ' ' + (j.description || '')).toLowerCase();
  taiwanPoints = text.includes('apac remote') ? 30 : 40;
} else if (j.taiwan_eligible === 'unclear') {
  taiwanPoints = 20;
} else if (j.taiwan_eligible === 'yes') {
  taiwanPoints = 30;
}

const asyncPoints = j.async_points || 0;
const rolePoints = j.role_points || 0;

let salaryPoints = 0;
const salaryText = (j.salary || '').toString();
const numbers = salaryText.match(/\d[\d,]*/g);
let maxSalary = 0;
if (numbers) {
  for (const n of numbers) {
    const value = parseInt(n.replace(/,/g, ''), 10);
    if (value > maxSalary) maxSalary = value;
  }
}
if (maxSalary > 5000) {
  salaryPoints = 25;
} else if (maxSalary > 3000) {
  salaryPoints = 15;
} else if (salaryText) {
  salaryPoints = 10;
}

const total = taiwanPoints + asyncPoints + rolePoints + salaryPoints;

j.score_taiwan = taiwanPoints;
j.score_async = asyncPoints;
j.score_role = rolePoints;
j.score_salary = salaryPoints;
j.score = Math.min(100, total);

return { json: j };

const j = $input.item.json;

const onePass = (
  j.taiwan_eligible !== 'no' &&
  j.location_risk !== 'high' &&
  j.timezone_risk !== 'high' &&
  !j.hardFilterReject &&
  !j.asyncHardReject
);

if (!onePass) {
  j.decision = 'reject';
  j.reject_category = j.reject_category || (j.taiwan_eligible === 'no' ? 'taiwan_ineligible' : 'high_risk');
  j.date_rejected = new Date().toISOString().slice(0, 10);
  j.reason = j.reason || ('Rejected: taiwan_eligible=' + j.taiwan_eligible + ', location_risk=' + j.location_risk + ', timezone_risk=' + j.timezone_risk);
  j.application_status = 'Rejected';
} else if (j.score < 70) {
  j.decision = 'reject';
  j.reject_category = 'low_score';
  j.date_rejected = new Date().toISOString().slice(0, 10);
  j.reason = 'Score below threshold: ' + j.score;
  j.application_status = 'Rejected';
} else if (
  j.taiwan_eligible === 'yes' &&
  j.score >= 85 &&
  (j.async_level === 'high' || j.async_level === 'medium') &&
  j.location_risk === 'low' &&
  (j.timezone_risk === 'low' || j.timezone_risk === 'medium')
) {
  j.decision = 'apply';
  j.application_status = 'Ready to Apply';
} else if (
  j.taiwan_eligible === 'unclear' &&
  j.score >= 85 &&
  j.location_risk === 'medium'
) {
  j.decision = 'manual_check';
  j.application_status = 'Manual Review';
} else {
  j.decision = 'manual_check';
  j.application_status = 'Review Recommended';
}

j.why_good_fit = 'Role: ' + (j.role_category || 'n/a') + ' | Async: ' + (j.async_level || 'n/a') + ' | Taiwan: ' + (j.taiwan_eligible || 'n/a') + ' | Score: ' + j.score;

return { json: j };

const original = $('Prepare Cover Letter Prompt').item.json;
const response = $input.item.json;

let text = '';
if (Array.isArray(response.content) && response.content.length && response.content[0].text) {
  text = response.content[0].text;
}

const j = original;
j.cover_letter_draft = text || 'Cover letter generation failed - draft manually.';

return { json: j };

const j = $input.item.json;
const lines = [];
lines.push('High score job alert (85+)');
lines.push('');
lines.push(j.job_title + ' at ' + j.company);
lines.push('Score: ' + j.score);
lines.push('Taiwan eligible: ' + j.taiwan_eligible);
lines.push('Salary: ' + (j.salary || 'Not listed'));
lines.push('Apply link: ' + j.job_url);
lines.push('');
lines.push('Suggested cover letter draft:');
lines.push(j.cover_letter_draft || 'Not generated');
j.instant_alert_text = lines.join('\n');
return { json: j };

const all = $input.all().map(function (item) { return item.json; });

const filtered = all.filter(function (j) { return j.decision === 'apply' || j.decision === 'manual_check'; });
const rejected = all.filter(function (j) { return j.decision === 'reject'; });

const top = filtered.slice().sort(function (a, b) { return (b.score || 0) - (a.score || 0); }).slice(0, 5);
const manualCheck = filtered.filter(function (j) { return j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70; });

function countBy(category) {
  return rejected.filter(function (j) { return j.reject_category === category; }).length;
}

const usOnlyCount = countBy('us_only');
const euOnlyCount = countBy('eu_only');
const hybridCount = countBy('hybrid');
const timezoneCount = countBy('timezone');
const otherRegionCount = countBy('other_region_locked') + countBy('work_permit') + countBy('must_be_based_in');

const lines = [];
lines.push('Daily Taiwan Eligible Async Remote Jobs');
lines.push('');
lines.push('Top jobs today:');
lines.push('');

if (top.length === 0) {
  lines.push('No jobs cleared the score 70 bar today.');
} else {
  top.forEach(function (j, idx) {
    lines.push((idx + 1) + '. ' + j.job_title);
    lines.push('Company: ' + j.company);
    lines.push('Score: ' + j.score);
    lines.push('Taiwan eligible: ' + j.taiwan_eligible);
    lines.push('Reason: ' + j.taiwan_reason);
    lines.push('Async level: ' + j.async_level);
    lines.push('Timezone risk: ' + j.timezone_risk);
    lines.push('Salary: ' + (j.salary || 'Not listed'));
    lines.push('Why it fits Jerry: ' + j.why_good_fit);
    lines.push('Apply link: ' + j.job_url);
    lines.push('');
  });
}

lines.push('Manual check:');
if (manualCheck.length === 0) {
  lines.push('None today.');
} else {
  manualCheck.forEach(function (j) {
    lines.push('- ' + j.job_title + ' at ' + j.company + ' (score ' + j.score + ') - ' + j.job_url);
  });
}
lines.push('');

lines.push('Rejected summary:');
lines.push('US only: ' + usOnlyCount);
lines.push('EU only: ' + euOnlyCount);
lines.push('Hybrid/onsite: ' + hybridCount);
lines.push('Timezone risk: ' + timezoneCount);
lines.push('Other region-restricted: ' + otherRegionCount);
lines.push('Total rejected: ' + rejected.length);

const digestText = lines.join('\n');

return [{ json: { digest_text: digestText, filtered_count: filtered.length, rejected_count: rejected.length } }];
